/ Allocate the memory for `c`.\\n        }\\n    }\\n\\n    /// @dev Returns the sorted set intersection between `a` and `b`.\\n    /// Note: Behaviour is undefined if inputs are not sorted and uniquified.\\n    function _intersection(uint256[] memory a, uint256[] memory b, uint256 signed)\\n        private\\n        pure\\n        returns (uint256[] memory c)\\n    {\\n        /// @solidity memory-safe-assembly\\n        assembly {\\n            let s := 0x20\\n            let aEnd := add(a, shl(5, mload(a)))\\n            let bEnd := add(b, shl(5, mload(b)))\\n            c := mload(0x40) // Set `c` to the free memory pointer.\\n            a := add(a, s)\\n            b := add(b, s)\\n            let k := c\\n            for {} iszero(or(gt(a, aEnd), gt(b, bEnd))) {} {\\n                let u := mload(a)\\n                let v := mload(b)\\n                if iszero(xor(u, v)) {\\n                    k := add(k, s)\\n                    mstore(k, u)\\n                    a := add(a, s)\\n                    b := add(b, s)\\n                    continue\\n                }\\n                if iszero(lt(add(u, signed), add(v, signed))) {\\n                    b := add(b, s)\\n                    continue\\n                }\\n                a := add(a, s)\\n            }\\n            mstore(c, shr(5, sub(k, c))) // Store the length of `c`.\\n            mstore(0x40, add(k, s)) // Allocate the memory for `c`.\\n        }\\n    }\\n\\n    /// @dev Returns the sorted set union of `a` and `b`.\\n    /// Note: Behaviour is undefined if inputs are not sorted and uniquified.\\n    function _union(uint256[] memory a, uint256[] memory b, uint256 signed)\\n        private\\n        pure\\n        returns (uint256[] memory c)\\n    {\\n        /// @solidity memory-safe-assembly\\n        assembly {\\n            let s := 0x20\\n            let aEnd := add(a, shl(5, mload(a)))\\n            let bEnd := add(b, shl(5, mload(b)))\\n            c := mload(0x40) // Set `c` to the free memory pointer.\\n            a := add(a, s)\\n            b := add(b, s)\\n            let k := c\\n            for {} iszero(or(gt(a, aEnd), gt(b, bEnd))) {} {\\n                let u := mload(a)\\n                let v := mload(b)\\n                if iszero(xor(u, v)) {\\n                    k := add(k, s)\\n                    mstore(k, u)\\n                    a := add(a, s)\\n                    b := add(b, s)\\n                    continue\\n                }\\n                if iszero(lt(add(u, signed), add(v, signed))) {\\n                    k := add(k, s)\\n                    mstore(k, v)\\n                    b := add(b, s)\\n                    continue\\n                }\\n                k := add(k, s)\\n                mstore(k, u)\\n                a := add(a, s)\\n            }\\n            for {} iszero(gt(a, aEnd)) {} {\\n                k := add(k, s)\\n                mstore(k, mload(a))\\n                a := add(a, s)\\n            }\\n            for {} iszero(gt(b, bEnd)) {} {\\n                k := add(k, s)\\n                mstore(k, mload(b))\\n                b := add(b, s)\\n            }\\n            mstore(c, shr(5, sub(k, c))) // Store the length of `c`.\\n            mstore(0x40, add(k, s)) // Allocate the memory for `c`.\\n        }\\n    }\\n}\\n"},{"name":"LibStorage","filePath":"utils/LibStorage.sol","kind":"library","inherits":[],"implements":[],"category":"library","externalFunctions":[],"internalFunctions":[{"name":"slot","visibility":"internal","stateMutability":"view","parameters":[{"name":"b","type":"Bump"}],"returnValues":[{"name":"result","type":"bytes32"}],"calls":[],"isVirtual":false,"sourceCode":"function slot(Bump storage b) internal view returns (bytes32 result) {\\n        /// @solidity memory-safe-assembly\\n        assembly {\\n            mstore(0x1f, sload(b.slot))\\n            mstore(0x04, _BUMPED_STORAGE_REF_SLOT_SEED)\\n            mstore(0x00, b.slot)\\n            result := keccak256(0x00,